/// <summary>
/// Bug 293935: CB705  - Item GST group is not copied from Source transaction
/// </summary>
[ExtensionOf(classStr(TAMRebateJournalTrans))]
final class METTAMRebateJournalTrans_Extension
{
    private str currentAggregatedStr;
    private METSalesUnit metSalesUnitId;
    private boolean metNeedUnitConversion;

}

Method.Source:
/// <summary>
/// Method to return the tax item group
/// </summary>
/// <returns><c>TaxItemGroup</c></returns>
public TaxItemGroup metGetTaxItemGroup()
{
    return taxItemGroup;
}

/// <summary>
/// CB201 - Rebate aggregation value parameter
/// </summary>
/// <param name = "_aggregatedStr">Aggregatore value</param>
/// <returns>Aggregatore value</returns>
public str parmCurrentAggregatedStr(str _aggregatedStr = currentAggregatedStr)
{
    currentAggregatedStr = _aggregatedStr;
    return currentAggregatedStr;
}

/// <summary>
/// Returns the default order unit of journal line.
/// </summary>
/// <returns>Default unit of measurement</returns>
public METSalesUnit metParmDefaultOrderUnit(METSalesUnit _salesUnit = metSalesUnitId)
{
    metSalesUnitId = _salesUnit;

    return metSalesUnitId;
}

/// <summary>
/// Should perform addl. unit conversion.
/// </summary>
/// <returns>true, if additional unit conversion is needed, otherwise false</returns>
public boolean metParmNeedUnitConversion(boolean _needUnitConversion = metNeedUnitConversion)
{
    metNeedUnitConversion = _needUnitConversion;

    return metNeedUnitConversion;
}
